package com.triathlon.prep.nextday.host;
import com.triathlon.prep.core.*;import com.triathlon.prep.core.nextday.*;import com.triathlon.prep.ui.FaceLibraryManagementView;
import java.io.IOException;import java.util.*;import java.util.function.*;
/** Safe paged projection and single-use staff actions. All SDK mutations use the Host worker. */
public final class LibraryHostSession implements AutoCloseable {
 private final NextDayModule module;private final VerificationModeSession authority;private final Verification.Clock clock;private final BooleanSupplier active;private final Consumer<Runnable> dispatch;private final Runnable updated;
 private final FaceLibraryTransferSession transfer;private final SafFaceTransfer files;private final String operationId=UUID.randomUUID().toString();
 private final Permit permit=new Permit();private long sequence;private int page;private volatile boolean closed;
 private FaceLibraryManagementView.State phase=FaceLibraryManagementView.State.LOADING;private String notice="",fileId="",exportKey="",keyLibrary="";private long keyEpoch,keyDeadline;private VerificationModeSession.Mode keyMode;private RaceRoster roster;
 private volatile FaceLibraryManagementView.Model offered;private final BooleanSupplier selectionKnown;private boolean restoreSucceeded;public boolean restored(){return restoreSucceeded;}private PreviousRestore previousRestore;private Supplier<String> previousBatch=()->"";
 public interface PreviousRestore {void restore(FaceEngine.Parameters pinned,FaceLibrary.MutationGuard lease)throws IOException;}
 public void restorePort(PreviousRestore port,Supplier<String> previous){previousRestore=port;previousBatch=Objects.requireNonNull(previous);}
 private VerificationModeSession.Snapshot modelControl,actionControl;private String actionLibrary="";private FaceEngine.Parameters actionParameters;private long actionStarted,actionDeadline;
 private static final class Permit {String key="",token="";long revision;
  synchronized void update(String next,boolean enabled){if(!enabled){key="";token="";return;}if(!key.equals(next)){key=next;token=UUID.randomUUID().toString();revision++;}}
  synchronized String token(){return token;}synchronized long revision(){return revision;}
  synchronized boolean take(String offered,long version){if(token.isEmpty()||!token.equals(offered)||revision!=version)return false;token="";return true;}
  synchronized void clear(){key="";token="";revision++;}
 }
 public LibraryHostSession(NextDayModule module,VerificationModeSession authority,Verification.Clock clock,BooleanSupplier active,Function<FaceLibraryTransferSession,SafFaceTransfer> filesFactory,Consumer<Runnable> dispatch,Runnable updated){
  this(module,authority,clock,active,filesFactory,dispatch,updated,null,()->true);
 }
 public LibraryHostSession(NextDayModule module,VerificationModeSession authority,Verification.Clock clock,BooleanSupplier active,Function<FaceLibraryTransferSession,SafFaceTransfer> filesFactory,Consumer<Runnable> dispatch,Runnable updated,FaceLibraryTransferSession.SourceCommit sourceCommit,BooleanSupplier selectionKnown){
  if(module==null||authority==null||clock==null||active==null||filesFactory==null||dispatch==null||updated==null)throw new IllegalArgumentException("Explicit library Host ports required");this.module=module;this.authority=authority;this.clock=clock;this.active=active;this.dispatch=dispatch;this.updated=updated;this.selectionKnown=Objects.requireNonNull(selectionKnown);transfer=new FaceLibraryTransferSession(module.library,authority,clock,module.engine::parameters,sourceCommit);files=filesFactory.apply(transfer);if(files==null)throw new IllegalArgumentException("File owner required");
 }
 public boolean imported(){return transfer.state()==FaceLibraryTransferSession.State.IMPORTED;}public boolean busy(){return files.busy();}public boolean closed(){return closed;}
 public String operationId(){return operationId;}public String fileId(){return fileId;}
 public boolean keyReady(){return !closed&&phase==FaceLibraryManagementView.State.READY&&!exportKey.isEmpty();}
 public void failure(String safeNotice){phase=FaceLibraryManagementView.State.FAILED;notice=safeNotice;dropKey();updated.run();}
 public void open(){phase=FaceLibraryManagementView.State.LOADING;updated.run();try{boolean ready=module.prepare();phase=ready?FaceLibraryManagementView.State.READY:FaceLibraryManagementView.State.FAILED;notice=ready?"只管理本场库；不改变报到记录。":module.preparationNotice()+"人数待核，当前不能激活或清理人脸库。";}catch(IOException|RuntimeException error){phase=FaceLibraryManagementView.State.FAILED;notice="人脸库读取或准备失败，原库未清理。";}updated.run();}
 private boolean usable(){FaceLibrary.Status s=module.library.status();FaceEngine.Parameters p=module.engine.parameters();return !closed&&active.getAsBoolean()&&authority.snapshot().state==VerificationModeSession.State.STABLE&&(s==FaceLibrary.Status.READY||s==FaceLibrary.Status.EMPTY)&&module.engine.readiness()==FaceEngine.Readiness.READY&&p!=null&&p.calibrated;}
 private boolean consume(String id,String token,long revision,int kind){FaceLibraryManagementView.Model model=model(roster);if(!operationId.equals(id)||!usableForAction(model,kind)||modelControl==null||!authority.allows(modelControl.currentMode,modelControl.epoch)||!permit.take(token,revision))return false;actionControl=modelControl;actionLibrary=module.library.snapshot().revision;actionParameters=module.engine.parameters();actionStarted=clock.elapsedMillis();actionDeadline=actionStarted+120000;sequence++;return true;}
 private boolean actionCurrent(){long now=clock.elapsedMillis();return !closed&&active.getAsBoolean()&&now>=actionStarted&&now<=actionDeadline&&actionControl!=null&&authority.allows(actionControl.currentMode,actionControl.epoch)&&module.library.snapshot().revision.equals(actionLibrary)&&same(actionParameters,module.engine.parameters());}
 private boolean usableForAction(FaceLibraryManagementView.Model m,int kind){switch(kind){case 0:return m.refreshEnabled;case 1:return m.exportEnabled;case 2:return m.chooseImportEnabled;case 3:return m.confirmImportEnabled;case 4:return m.cancelPreviewEnabled;case 5:return m.clearEnabled;case 6:return m.pageEnabled;case 8:return m.restoreEnabled;default:return m.backEnabled;}}
 public boolean refresh(String id,String token,long revision){if(!consume(id,token,revision,0))return false;open();return true;}
 public FaceLibraryTransferSession.Offer beginExport(String id,String token,long revision)throws IOException{
  if(!consume(id,token,revision,1)||!actionCurrent())return null;FaceLibraryTransferSession.Offer offer=transfer.beginExport();if(!actionCurrent()){transfer.cancel(offer.id);throw new IOException("Export request revoked");}fileId=offer.id;exportKey=offer.keyCode;keyLibrary=actionLibrary;keyEpoch=actionControl.epoch;keyMode=actionControl.currentMode;keyDeadline=clock.elapsedMillis()+120000;phase=FaceLibraryManagementView.State.EXPORTING;notice="请选择新输出文件，尚未确认导出完成。";updated.run();return offer;
 }
 public boolean beginChooseImport(String id,String token,long revision){if(!consume(id,token,revision,2))return false;transfer.cancel();dropKey();phase=FaceLibraryManagementView.State.CHOOSING_IMPORT;notice="请临时输入与库文件独立传递的密钥，再选择加密库文件。";updated.run();return true;}
 public FaceLibraryTransferSession.Offer inputKey(String code)throws IOException{if(phase!=FaceLibraryManagementView.State.CHOOSING_IMPORT||!usable()||!actionCurrent())throw new IOException("Import request no longer current");FaceLibraryTransferSession.Offer offer=transfer.beginImport(code);if(!actionCurrent()){transfer.cancel(offer.id);throw new IOException("Import request revoked");}fileId=offer.id;return offer;}
 public void writeExport(String id,String uri)throws IOException{if(!fileId.equals(id))throw new IOException("Export selection expired");files.exportTo(id,uri,this::completed);}
 public void readImport(String id,String uri)throws IOException{if(!fileId.equals(id))throw new IOException("Import selection expired");phase=FaceLibraryManagementView.State.PREFLIGHTING;updated.run();files.readImport(id,uri,this::completed);}
 private void completed(String id,SafFaceTransfer.Status status,boolean cleanup){dispatch.accept(()->{if(closed||!fileId.equals(id))return;
  phase=status==SafFaceTransfer.Status.REVIEW?FaceLibraryManagementView.State.IMPORT_REVIEW:status==SafFaceTransfer.Status.EXPORTED?FaceLibraryManagementView.State.READY:FaceLibraryManagementView.State.FAILED;
  notice=status==SafFaceTransfer.Status.REVIEW?"文件已认证并关闭，预检尚未激活；请核对摘要并明确确认。":status==SafFaceTransfer.Status.EXPORTED?"加密文件流已完成并关闭；请保存本次独立传递密钥。":cleanup?"文件操作未完成，原活动库保持不变。":"导出未完成且残留输出未确认清除，不可作为有效库使用。";
  if(status!=SafFaceTransfer.Status.EXPORTED)dropKey();updated.run();
 });}
 public String takeExportKey(){if(phase!=FaceLibraryManagementView.State.READY)return "";if(closed||exportKey.isEmpty()||!usable()||clock.elapsedMillis()>keyDeadline||!authority.allows(keyMode,keyEpoch)||!module.library.snapshot().revision.equals(keyLibrary)){dropKey();return "";}String key=exportKey;exportKey="";return key;}
 public void dropKey(){exportKey="";}
 public boolean confirmImport(String id,String preflight,String token,long revision,boolean confirmed){if(!confirmed||!fileId.equals(preflight)||!consume(id,token,revision,3))return false;phase=FaceLibraryManagementView.State.IMPORTING;updated.run();try{transfer.confirmImport(preflight);phase=FaceLibraryManagementView.State.READY;notice="本场人脸库已原子导入，报到记录保持不变。";page=0;}catch(IOException|RuntimeException error){phase=FaceLibraryManagementView.State.FAILED;notice="导入未完成，请核对活动库状态；未将预检视为成功。";}updated.run();return true;}
 public boolean restorePrevious(String id,String token,long revision,boolean confirmed){if(!confirmed||previousRestore==null||!consume(id,token,revision,8)||!actionCurrent())return false;restoreSucceeded=false;phase=FaceLibraryManagementView.State.LOADING;updated.run();try{previousRestore.restore(actionParameters,()->!closed&&active.getAsBoolean()&&clock.elapsedMillis()>=actionStarted&&clock.elapsedMillis()<=actionDeadline&&authority.allows(actionControl.currentMode,actionControl.epoch));restoreSucceeded=true;phase=FaceLibraryManagementView.State.READY;notice="已选择之前的人脸库，报到及核验记录不变。";}catch(IOException|RuntimeException error){phase=FaceLibraryManagementView.State.FAILED;notice="恢复未完成，原选择保持；请核对索引准备状态。";}updated.run();return true;}
 public boolean cancelPreview(String id,String preflight,String token,long revision){if(!fileId.equals(preflight)||!consume(id,token,revision,4))return false;transfer.cancel();fileId="";phase=FaceLibraryManagementView.State.READY;notice="已取消本次预检，原库保持不变。";updated.run();return true;}
 public boolean clear(String id,String token,long revision,boolean confirmed){if(!confirmed||!consume(id,token,revision,5))return false;FaceLibrary.Snapshot old=module.library.snapshot();VerificationModeSession.Snapshot m=authority.snapshot();FaceEngine.Parameters p=module.engine.parameters();phase=FaceLibraryManagementView.State.CLEARING;updated.run();try{
  module.library.importSnapshot(new FaceLibrary.Snapshot(UUID.randomUUID().toString(),old.scope,Collections.emptyList()),lockedGuard(()->!closed&&active.getAsBoolean()&&authority.allows(m.currentMode,m.epoch)&&module.library.snapshot().revision.equals(old.revision)&&same(p,module.engine.parameters())));phase=FaceLibraryManagementView.State.READY;notice="本场人脸库已清理，原报到记录未撤销。";page=0;
 }catch(IOException|RuntimeException error){phase=FaceLibraryManagementView.State.FAILED;notice="清理未完成，请核对活动库状态；原报到记录未改变。";}updated.run();return true;}
 private FaceLibrary.MutationGuard lockedGuard(FaceLibrary.MutationGuard guard){return new FaceLibrary.MutationGuard(){public boolean current(){return guard.current();}public void commit(FaceLibrary.Mutation mutation)throws IOException{synchronized(authority){if(!current())throw new IOException("Library clear revoked");mutation.run();}}};}
 private static String modelIdentity(FaceLibrary.Scope scope){return (scope.mode==Verification.Mode.TEST?"TEST合成标记":"百度V9")+"；模型指纹："+scope.modelFingerprint+"；特征类型："+scope.featureType;}
 private static boolean same(FaceEngine.Parameters a,FaceEngine.Parameters b){return a!=null&&b!=null&&b.calibrated&&a.revision==b.revision&&Double.compare(a.matchThreshold,b.matchThreshold)==0&&Double.compare(a.minimumMargin,b.minimumMargin)==0&&a.maximumFrameAgeMillis==b.maximumFrameAgeMillis;}
 public boolean page(int next,String id,String token,long revision){if(next<0||next>=Math.max(1,(module.library.snapshot().entries.size()+99)/100)||!consume(id,token,revision,6))return false;page=next;updated.run();return true;}
 /** Only immutable offered metadata and a short nonce lock are touched by immediate UI back. */
 public boolean takeBack(String id,String token,long revision){FaceLibraryManagementView.Model m=offered;return !closed&&m!=null&&m.backEnabled&&m.operationId.equals(id)&&m.requestToken.equals(token)&&m.revision==revision&&permit.take(token,revision);}
 public void cancelChoice(){transfer.cancel();files.cancel();dropKey();fileId="";phase=FaceLibraryManagementView.State.READY;notice="文件选择已取消，原库保持不变。";sequence++;updated.run();}
 public FaceLibraryManagementView.Model model(RaceRoster roster){this.roster=roster;FaceLibrary.Snapshot snapshot=module.library.snapshot();FaceLibrary.Status status=module.library.status();boolean selected=selectionKnown.getAsBoolean();boolean known=selected&&(status==FaceLibrary.Status.READY||status==FaceLibrary.Status.EMPTY);int total=known?snapshot.entries.size():0;int pages=Math.max(1,(total+99)/100);page=Math.min(page,pages-1);
  List<FaceLibraryManagementView.PersonRow> rows=new ArrayList<>();for(int i=page*100;i<Math.min(total,page*100+100);i++){FaceLibrary.Entry entry=snapshot.entries.get(i);rows.add(new FaceLibraryManagementView.PersonRow(snapshot.revision+":"+entry.id,entry.bib,entry.name,entry.group,FaceLibraryManagementView.RegistrationStatus.ENROLLED,"本场活动库登记"));}
  String event=roster!=null&&roster.batchId.equals(snapshot.scope.batchId)?roster.eventName:selected?"来源人脸库":"未选择人脸库";FaceLibrary.Scope candidate=transfer.candidateScope();FaceLibraryManagementView.ImportPreview preview=null;if(phase==FaceLibraryManagementView.State.IMPORT_REVIEW&&transfer.state()==FaceLibraryTransferSession.State.REVIEW&&!transfer.candidateRevision().isEmpty())preview=new FaceLibraryManagementView.ImportPreview(fileId,"未提供",candidate==null?"待核":candidate.batchId,candidate==null?"待核":modelIdentity(candidate),transfer.candidateRevision(),transfer.candidateCount(),total,"来源库已认证；确认后选择该完整来源库，不合并或修改报到名单。");
  modelControl=authority.snapshot();boolean visible=!closed&&active.getAsBoolean()&&modelControl.state==VerificationModeSession.State.STABLE;boolean busy=phase==FaceLibraryManagementView.State.LOADING||phase==FaceLibraryManagementView.State.EXPORTING||phase==FaceLibraryManagementView.State.CHOOSING_IMPORT||phase==FaceLibraryManagementView.State.PREFLIGHTING||phase==FaceLibraryManagementView.State.IMPORTING||phase==FaceLibraryManagementView.State.CLEARING;
  FaceEngine.Parameters p=module.engine.parameters();String key=operationId+"/"+modelControl.epoch+"/"+snapshot.revision+"/"+status+"/"+(p==null?"":p.revision+"/"+p.calibrated+"/"+p.matchThreshold+"/"+p.minimumMargin+"/"+p.maximumFrameAgeMillis)+"/"+phase+"/"+page+"/"+sequence+"/"+fileId;permit.update(key,visible);
  boolean ready=visible&&usable(),idle=!busy&&preview==null;int indexed=ready&&status==FaceLibrary.Status.READY?total:0;
  offered=new FaceLibraryManagementView.Model(snapshot.scope.mode==Verification.Mode.TEST,event,selected?snapshot.scope.batchId:"未选择批次",modelIdentity(snapshot.scope),known?snapshot.revision:"待核",selected?FaceLibraryManagementView.LibraryState.valueOf(status.name()):FaceLibraryManagementView.LibraryState.ABSENT,total,indexed,known,phase,notice,page,pages,total,rows,preview,operationId,permit.token(),permit.revision(),ready&&selected&&idle&&total>0,ready&&idle,ready&&preview!=null,visible&&preview!=null,ready&&selected&&idle&&total>0,visible&&idle,visible,visible&&idle&&pages>1,previousBatch.get(),previousRestore!=null&&ready&&idle&&(status==FaceLibrary.Status.READY||status==FaceLibrary.Status.EMPTY)&&!previousBatch.get().isEmpty()&&phase==FaceLibraryManagementView.State.READY);return offered;
 }
 public void close(){closed=true;permit.clear();dropKey();transfer.cancel();files.close();}
}







